// ── Haversine distance (metres) ───────────────────────────────
function haversineDist(lat1, lon1, lat2, lon2) {
  const R = 6_371_000;
  const f1 = (lat1 * Math.PI) / 180, f2 = (lat2 * Math.PI) / 180;
  const df = ((lat2 - lat1) * Math.PI) / 180, dl = ((lon2 - lon1) * Math.PI) / 180;
  const a = Math.sin(df / 2) ** 2 + Math.cos(f1) * Math.cos(f2) * Math.sin(dl / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

/**
 * Resample waypoints at uniform metric intervals.
 * Guarantees pts[0] === waypoints[0] and pts[last] === waypoints[last].
 */
export function resampleRoute(waypoints, stepMeters = 10) {
  const segs = [];
  let total = 0;
  for (let i = 0; i < waypoints.length - 1; i++) {
    const [lat1, lng1] = waypoints[i], [lat2, lng2] = waypoints[i + 1];
    const d = haversineDist(lat1, lng1, lat2, lng2);
    segs.push({ lat1, lng1, lat2, lng2, d, start: total });
    total += d;
  }
  const lerp = (dist) => {
    let s = segs[segs.length - 1];
    for (const seg of segs) { if (dist <= seg.start + seg.d) { s = seg; break; } }
    const t = s.d > 0 ? (dist - s.start) / s.d : 0;
    return { lat: s.lat1 + (s.lat2 - s.lat1) * t, lng: s.lng1 + (s.lng2 - s.lng1) * t, dist, total };
  };
  const n   = Math.floor(total / stepMeters);
  const pts = Array.from({ length: n + 1 }, (_, i) => lerp(Math.min(i * stepMeters, total)));
  pts[0]              = { lat: waypoints[0][0],                          lng: waypoints[0][1],                          dist: 0,     total };
  pts[pts.length - 1] = { lat: waypoints[waypoints.length - 1][0], lng: waypoints[waypoints.length - 1][1], dist: total, total };
  return pts;
}
